parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "architectural_risks": {
      "type": "array",
      "description": "Open, evidence-driven set. No fixed length -- do not pad or truncate to match a target count. Each item's finding_id must be unique within this array.",
      "items": {
        "type": "object",
        "properties": {
          "risk_name": {
            "type": "string"
          },
          "finding_id": {
            "type": "string",
            "description": "GENERATED, not chosen from a fixed list. Format: {CATEGORY-SLUG}-{NN}, where CATEGORY-SLUG is derived from this finding's own risk_category (see mapping below) and NN is a two-digit sequence number starting at 01, unique within that category for this output. Example: if risk_category is 'Upgradeability', finding_id is 'UPGRADEABILITY-01' (or -02 if a second, independent Upgradeability finding exists in this run). NOT a stable cross-protocol key -- do not assume this ID means the same thing across two different protocol runs. NOT stable across repeated runs on the SAME protocol either -- use claim_id for that (see below).",
            "pattern": "^(CENTRALISATION|UPGRADEABILITY|DEPENDENCY|ECONOMIC-DEPENDENCY|ACCESS-CONTROL|GOVERNANCE|TRUST-BOUNDARY|COMPOSABILITY|ASSET-CUSTODY|OPERATIONAL-RESILIENCE)-[0-9]{2}$"
          },
          "risk_category": {
            "type": "string",
            "description": "Exact human-readable enum value, WITH a space -- e.g. 'Asset Custody', 'Economic Dependency'. This is a different format from the hyphenated slug used inside finding_id (e.g. 'ASSET-CUSTODY-01') -- do not use the hyphenated slug here.",
            "enum": [
              "Centralisation",
              "Upgradeability",
              "Dependency",
              "Economic Dependency",
              "Access Control",
              "Governance",
              "Trust Boundary",
              "Composability",
              "Asset Custody",
              "Operational Resilience"
            ]
          },
          "claim_id": {
            "type": "string",
            "description": "STABLE identifier for the underlying architectural proposition this finding makes, independent of finding_id and risk_category (both of which are known to vary across repeated runs on identical input -- see reproducibility test results). Format: {PROTOCOL-SLUG}-{TOKEN}...(1-6 mechanism tokens after the protocol slug; a single-token claim is valid when the finding genuinely turns on one mechanism), built ONLY from literal function/variable/state-variable names that already appear verbatim in this finding's own evidence array, uppercased, sorted alphabetically, hyphen-joined. Underscores within a token (e.g. Solidity internal-function convention '_setImplementation') are preserved, not stripped. Never derived from risk_category, severity, risk_name, or any other judgment field -- those are exactly the fields that drift between runs. See CLAIM ID & VALIDATION TARGET for the full algorithm and a worked example.",
            "pattern": "^[A-Z0-9_]+(-[A-Z0-9_]+){1,7}$"
          },
          "validation_target": {
            "type": "object",
            "description": "Structured target for downstream deterministic (Foundry) validation. Exists so validation can key against a stable proposition instead of this run's finding_id/risk_category placement.",
            "properties": {
              "protocol": {
                "type": "string",
                "description": "Protocol name/slug as given in this run's input (e.g. 'Venus', 'Aave')."
              },
              "primary_component": {
                "type": "string",
                "description": "Single contract/module name most directly responsible for this claim, copied verbatim from the Architecture Model's contract_profile.name or affected_components -- not paraphrased."
              },
              "mechanism_tokens": {
                "type": "array",
                "items": { "type": "string" },
                "description": "The literal function/variable/state names claim_id was built from, copied verbatim from this finding's evidence. Same tokens used to build claim_id, listed here as a structured array (not uppercased/hyphenated -- keep original casing as it appears in source, e.g. 'exchangeRateStoredInternal', not 'EXCHANGERATESTOREDINTERNAL')."
              },
              "dependency_chain": {
                "type": "array",
                "items": { "type": "string" },
                "description": "Ordered causal chain of function/state names from the outermost policy-facing call to the root data source, e.g. ['exchangeRateStoredInternal', 'getCashPrior', 'balanceOf']. Empty array if this claim has no meaningful multi-step chain (e.g. a single-hop privilege finding)."
              }
            },
            "required": ["protocol", "primary_component", "mechanism_tokens", "dependency_chain"]
          },
          "severity": {
            "type": "string",
            "enum": [
              "Critical",
              "High",
              "Medium",
              "Low",
              "Informational"
            ]
          },
          "description": {
            "type": "string"
          },
          "architectural_rationale": {
            "type": "string"
          },
          "affected_components": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "supporting_observations": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "evidence": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "governance_model": {
            "type": "string",
            "description": "ONE value for this finding's single most central privileged entity -- never an object, never per-entity. If multiple entities are involved, classify only the one most directly responsible for the exposure and describe the others in evidence/description text instead.",
            "enum": [
              "EOA",
              "Multisig",
              "Timelock",
              "DAO",
              "Unknown"
            ]
          },
          "runtime_validation_candidate": {
            "type": "boolean"
          },
          "runtime_validation_rationale": {
            "type": "string"
          },
          "related_risks": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "finding_id values of related findings from THIS SAME output only."
          },
          "mitigation_considerations": {
            "type": "array",
            "description": "High-level architectural considerations only -- not evidence, not confirmed vulnerabilities, not exploit instructions, not claims of exploitability. This is the one place recommendations are allowed; nothing elsewhere in the output should read as a recommendation.",
            "items": {
              "type": "string"
            }
          },
          "confidence": {
            "type": "number",
            "minimum": 0,
            "maximum": 1,
            "description": "Your remaining uncertainty about the SPECIFIC causal claim being made -- NOT whether evidence exists (every reported finding already has evidence by construction, per FINDING GENERATION). Must reflect genuine per-finding variation; do not default to 1.0 or 0.95 for every finding. See the CONFIDENCE section of the system prompt for the full anchored scale (0.95-1.00 / 0.85-0.94 / 0.70-0.84 / 0.50-0.69 / 0.30-0.49 / 0.00-0.29) and worked example."
          },
          "confidence_rationale": {
            "type": "string",
            "description": "Short rationale for the confidence score specifically (not the risk itself -- that's architectural_rationale). Must name the specific reason confidence is high, moderate, or low: evidence completeness, inference distance, corroboration, scope match. Do not write a generic sentence like 'strong architectural evidence supports this finding.'"
          }
        },
        "required": [
          "finding_id",
          "risk_name",
          "risk_category",
          "claim_id",
          "validation_target",
          "severity",
          "description",
          "architectural_rationale",
          "affected_components",
          "supporting_observations",
          "evidence",
          "governance_model",
          "runtime_validation_candidate",
          "runtime_validation_rationale",
          "related_risks",
          "mitigation_considerations",
          "confidence",
          "confidence_rationale"
        ]
      }
    }
  },
  "required": [
    "architectural_risks"
  ]
}

