function esc(s) {
    if (s === null || s === undefined) return "";
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
function fmt3(x) {
    if (x === null || x === undefined || Number.isNaN(x)) return "--";
    return Number(x).toFixed(3);
