function pct(x) {
    if (x === null || x === undefined || Number.isNaN(x)) return "--";
    return Math.round(Number(x) * 100) + "%";
}
function normalizeName(s) {
    return String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
