parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "architectural_risks": {
      "type": "array",
      "description": "Same array shape Node 07 produces. Audit/incident-sourced findings are additive to Node 07's findings, not a replacement -- both flow into Node 13 unmodified. Open, evidence-driven set. No fixed length -- do not pad or truncate. Each item's finding_id must be unique within this array. One object per DISTINCT finding in the source document -- never merge two separate findings into one object, never split one finding into two.",
      "items": {
        "type": "object",
        "properties": {
          "risk_name": { "type": "string" },
          "finding_id": {
            "type": "string",
            "description": "GENERATED for this run, same rule as Node 07: {CATEGORY-SLUG}-{NN}. NOT a stable cross-run key -- claim_id is.",
            "pattern": "^(CENTRALISATION|UPGRADEABILITY|DEPENDENCY|ECONOMIC-DEPENDENCY|ACCESS-CONTROL|GOVERNANCE|TRUST-BOUNDARY|COMPOSABILITY|ASSET-CUSTODY|OPERATIONAL-RESILIENCE)-[0-9]{2}$"
          },
          "risk_category": {
            "type": "string",
            "description": "Exact enum value, WITH a space. Choose the single best fit -- if the source finding spans two categories, pick the one the source document's own severity/impact language centers on.",
            "enum": [
              "Centralisation", "Upgradeability", "Dependency", "Economic Dependency",
              "Access Control", "Governance", "Trust Boundary", "Composability",
              "Asset Custody", "Operational Resilience"
            ]
          },
          "claim_id": {
            "type": "string",
            "description": "STABLE identifier, same algorithm as Node 07: built ONLY from literal function/variable/state-variable names that appear VERBATIM in this finding's own evidence array, uppercased, sorted alphabetically, hyphen-joined, protocol-slug-prefixed. Never derived from risk_category, severity, or risk_name. This is the join key the dismissed-finding tracker will use to match this audit finding against today's Node 16 status for the same underlying claim -- get it right, don't approximate it.",
            "pattern": "^[A-Z0-9_]+(-[A-Z0-9_]+){1,7}$"
          },
          "validation_target": {
            "type": "object",
            "properties": {
              "protocol": { "type": "string" },
              "primary_component": {
                "type": "string",
                "description": "Contract/module name copied verbatim from the source document (e.g. from a 'Lines of code' link or file path), not paraphrased."
              },
              "mechanism_tokens": {
                "type": "array",
                "items": { "type": "string" },
                "description": "Literal function/variable names copied verbatim from the source, original casing preserved. Same tokens claim_id is built from."
              },
              "dependency_chain": {
                "type": "array",
                "items": { "type": "string" },
                "description": "Ordered causal chain from outermost policy-facing call to root data source, if the source describes one. Empty array if not applicable."
              }
            },
            "required": ["protocol", "primary_component", "mechanism_tokens", "dependency_chain"]
          },
          "severity": {
            "type": "string",
            "enum": ["Critical", "High", "Medium", "Low", "Informational"],
            "description": "Normalized FROM the source's own rating -- see provenance.original_severity_label for the verbatim original. Do not re-assess severity yourself; map the source's rating onto this enum as faithfully as possible and note any ambiguity in confidence_rationale."
          },
          "description": { "type": "string" },
          "architectural_rationale": { "type": "string" },
          "affected_components": { "type": "array", "items": { "type": "string" } },
          "supporting_observations": { "type": "array", "items": { "type": "string" } },
          "evidence": {
            "type": "array",
            "items": { "type": "string" },
            "description": "VERBATIM quotes from the source document only. No paraphrasing. Every string here must be traceable to an exact sentence/code excerpt in the source."
          },
          "governance_model": {
            "type": "string",
            "enum": ["EOA", "Multisig", "Timelock", "DAO", "Unknown"],
            "description": "Almost always 'Unknown' for audit-sourced findings unless the source document explicitly discusses who controls the relevant privileged role -- do not guess."
          },
          "runtime_validation_candidate": { "type": "boolean" },
          "runtime_validation_rationale": { "type": "string" },
          "related_risks": { "type": "array", "items": { "type": "string" } },
          "mitigation_considerations": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Pull directly from the source's own 'Recommended Mitigation' section if present, verbatim or near-verbatim. Do not invent new mitigation advice not present in the source."
          },
          "confidence": {
            "type": "number",
            "minimum": 0,
            "maximum": 1,
            "description": "Confidence in the EXTRACTION being faithful to the source, not confidence in whether the underlying vulnerability is real -- the source document already establishes that. Should generally be high (0.85-1.0) for a clearly-stated, unambiguous finding in a primary-source document; lower if the source is secondary/summarized rather than the original finding text, or if key fields (e.g. affected component) had to be inferred rather than read directly."
          },
          "confidence_rationale": { "type": "string" },

          "provenance": {
            "type": "object",
            "description": "NEW field, not present in Node 07's schema. Node 13/16 will not read this -- it exists for the dismissed-finding tracker (a later node) to key off. Node 13 should simply ignore it, which requires no change to Node 13 at all.",
            "properties": {
              "source_type": {
                "type": "string",
                "enum": ["AUDIT_FINDING", "INCIDENT_POSTMORTEM", "BUG_BOUNTY_REPORT", "OTHER"]
              },
              "source_firm": {
                "type": "string",
                "description": "e.g. 'Code4rena', 'Sigma Prime', 'Certik', 'Chaos Labs'. Verbatim as stated in the source, not inferred."
              },
              "source_document_title": { "type": "string" },
              "source_url": {
                "type": "string",
                "description": "The exact URL or file this was extracted from. Required -- every extracted finding must be traceable back to its source."
              },
              "date_flagged": {
                "type": "string",
                "description": "ISO 8601 date (YYYY-MM-DD) the finding was ORIGINALLY raised/published -- not today's date, not the date of parsing. If the source gives only a month or year, use the most specific value available and note the imprecision in original_disposition.extraction_confidence's sibling reasoning (in description or confidence_rationale)."
              },
              "original_severity_label": {
                "type": ["string", "null"],
                "description": "The EXACT severity label/text as it appears in the source (e.g. 'Medium (M-10)', 'High'), before normalization into the fixed severity enum above. Null if the source document states no explicit severity label at all -- do not invent one."
              },
              "original_disposition": {
                "type": "object",
                "properties": {
                  "category": {
                    "type": "string",
                    "enum": ["DISMISSED_AS_INTENDED", "ACKNOWLEDGED_NO_FIX", "FIXED", "PARTIALLY_FIXED", "UNKNOWN"],
                    "description": "UNKNOWN unless the source document itself explicitly states a resolution/status. Do not infer disposition from severity or from outside knowledge of what later happened -- that context belongs in a separate, clearly-labeled note, not in this field."
                  },
                  "verbatim_quote": {
                    "type": ["string", "null"],
                    "description": "The exact quoted sentence establishing the disposition, or null if category is UNKNOWN."
                  },
                  "quote_location": {
                    "type": ["string", "null"],
                    "description": "Where in the source this was found, e.g. 'sponsor comment', 'mitigation-review appendix', 'report status column'. Null if verbatim_quote is null."
                  },
                  "extraction_confidence": {
                    "type": "string",
                    "enum": ["VERIFIED_PRIMARY_QUOTE", "SECONDARY_SOURCE_UNVERIFIED", "NOT_STATED"],
                    "description": "VERIFIED_PRIMARY_QUOTE only if verbatim_quote comes directly from the primary source document being parsed in this run. If the disposition is only known from a different, secondary document, use SECONDARY_SOURCE_UNVERIFIED and say so in verbatim_quote's surrounding context -- never present a secondary-sourced claim as if it were primary."
                  }
                },
                "required": ["category", "verbatim_quote", "quote_location", "extraction_confidence"]
              }
            },
            "required": ["source_type", "source_firm", "source_document_title", "source_url", "date_flagged", "original_severity_label", "original_disposition"]
          }
        },
        "required": [
          "finding_id", "risk_name", "risk_category", "claim_id", "validation_target",
          "severity", "description", "architectural_rationale", "affected_components",
          "supporting_observations", "evidence", "governance_model",
          "runtime_validation_candidate", "runtime_validation_rationale", "related_risks",
          "mitigation_considerations", "confidence", "confidence_rationale", "provenance"
        ]
      }
    }
  },
  "required": ["architectural_risks"]
}
